#include <Arduino.h>
#include <Servo.h>
#include <TM1637Display.h>

Servo tracker;
TM1637Display display(4, 5);
int angle = 90;
bool automaticMode = true;
bool rawButton = HIGH;
bool stableButton = HIGH;
unsigned long buttonChanged = 0;
unsigned long lastMove = 0;
unsigned long lastDisplay = 0;
unsigned long lowSince = 0;
unsigned long lastReport = 0;
bool lowPending = false;
bool alarmActive = false;
bool charging = false;

void setup() {
  pinMode(2, INPUT_PULLUP);
  pinMode(6, OUTPUT);
  Serial.begin(9600);
  tracker.attach(9);
  tracker.write(angle);
  display.setBrightness(5);
  display.showNumberDec(0);
}

void loop() {
  unsigned long now = millis();
  bool reading = digitalRead(2);
  if (reading != rawButton) {
    rawButton = reading;
    buttonChanged = now;
  }
  if (now - buttonChanged >= 40 && stableButton != rawButton) {
    stableButton = rawButton;
    if (stableButton == LOW) {
      automaticMode = !automaticMode;
      Serial.println(automaticMode ? "automatic" : "manual calibration: adjust relative illumination to set angle");
    }
  }

  if (now - lastMove >= 20) {
    lastMove = now;
    int left = analogRead(A0);
    int right = analogRead(A1);
    if (automaticMode) {
      int difference = left - right;
      if (difference > 20 && angle < 180) ++angle;
      else if (difference < -20 && angle > 0) --angle;
    } else {
      // In calibration mode the two light sensors are manual angle controls.
      // Equal illumination selects center; shading either side selects travel.
      angle = (int)map((long)left - right, -1023L, 1023L, 0L, 180L);
      angle = constrain(angle, 0, 180);
    }
    tracker.write(angle);
  }

  float voltage = analogRead(A2) * (5.0f / 1023.0f);
  bool newCharging = voltage >= 3.0f;
  if (newCharging != charging) {
    charging = newCharging;
    Serial.println(charging ? "charge voltage adequate" : "charge voltage low");
  }
  if (now - lastDisplay >= 200) {
    lastDisplay = now;
    display.showNumberDec((int)(voltage * 100.0f + 0.5f), false);
  }

  if (voltage < 3.0f) {
    if (!lowPending) {
      lowPending = true;
      lowSince = now;
    }
    if (now - lowSince >= 10000UL) {
      if (!alarmActive) {
        alarmActive = true;
        tone(6, 2000);
        Serial.println("low charge");
        lastReport = now;
      } else if (now - lastReport >= 1000UL) {
        Serial.println("low charge");
        lastReport = now;
      }
    }
  } else {
    lowPending = false;
    if (alarmActive) {
      noTone(6);
      alarmActive = false;
    }
  }
}
